import type { ParsedApi, ToolDef } from "./types.js";

interface SmokeCase {
  name: string;
  method: string;
  path: string;
  pathArgs: Record<string, unknown>;
  queryArgs: Record<string, unknown>;
}

/**
 * Produce a standalone `node:test` file (as a string) that exercises every
 * read-only (GET/HEAD/OPTIONS) tool against the API's first server.
 *
 * The generated file imports nothing from this project: it only uses the Node
 * built-in test runner, `assert` and global `fetch`.
 */
export function generateSmokeTests(api: ParsedApi): string {
  const baseUrl = normalizeBaseUrl(api.baseUrls[0] ?? "");
  const cases = api.tools.filter(isReadOnly).map(buildSmokeCase);

  const lines: string[] = [];
  lines.push("// Generated by openapimcp smoke-test generator. Do not edit by hand.");
  lines.push(`// ${api.title} ${api.version}: ${cases.length} read-only operation(s).`);
  lines.push("// Run with: node --test <this-file>");
  lines.push("");
  lines.push('import { test } from "node:test";');
  lines.push('import assert from "node:assert/strict";');
  lines.push("");
  lines.push(`const BASE_URL = ${JSON.stringify(baseUrl)};`);
  lines.push("");
  lines.push("function buildUrl(baseUrl, path, pathArgs, queryArgs) {");
  lines.push('  const base = baseUrl || "http://localhost";');
  lines.push('  const resolved = path.replace(/\\{([^}]+)\\}/g, (match, key) => {');
  lines.push('    const value = Object.prototype.hasOwnProperty.call(pathArgs, key) ? pathArgs[key] : "1";');
  lines.push('    return encodeURIComponent(value === undefined ? "1" : String(value));');
  lines.push("  });");
  lines.push('  const relative = resolved.replace(/^\\/+/, "");');
  lines.push('  const url = new URL(relative, base.endsWith("/") ? base : base + "/");');
  lines.push("  for (const key of Object.keys(queryArgs)) {");
  lines.push("    const value = queryArgs[key];");
  lines.push("    if (value === undefined || value === null) continue;");
  lines.push('    url.searchParams.set(key, Array.isArray(value) ? value.join(",") : String(value));');
  lines.push("  }");
  lines.push("  return url;");
  lines.push("}");
  lines.push("");
  lines.push(`const CASES = ${JSON.stringify(cases, null, 2)};`);
  lines.push("");
  lines.push("for (const item of CASES) {");
  lines.push('  test(item.name + " returns a non-error status", async () => {');
  lines.push("    const url = buildUrl(BASE_URL, item.path, item.pathArgs, item.queryArgs);");
  lines.push("    const response = await fetch(url, { method: item.method });");
  lines.push('    assert.ok(response.status < 500, item.name + " -> " + response.status);');
  lines.push("  });");
  lines.push("}");
  lines.push("");

  return lines.join("\n");
}

/**
 * Build a plausible argument object for a tool. Schema `default` and the first
 * `enum` value win; otherwise numbers -> 1, booleans -> true, strings -> "1",
 * arrays -> ["1"] and objects -> {}.
 */
export function sampleArgs(tool: ToolDef): Record<string, unknown> {
  const args: Record<string, unknown> = {};
  for (const param of tool.params) {
    args[param.argName] = sampleValue(param.schema);
  }
  return args;
}

function buildSmokeCase(tool: ToolDef): SmokeCase {
  const args = sampleArgs(tool);
  const pathArgs: Record<string, unknown> = {};
  const queryArgs: Record<string, unknown> = {};

  for (const param of tool.params) {
    const value = args[param.argName];
    if (param.location === "path") pathArgs[param.origName ?? param.argName] = value;
    else if (param.location === "query") queryArgs[param.origName ?? param.argName] = value;
  }

  return {
    name: tool.name,
    method: String(tool.method || "get").toUpperCase(),
    path: tool.path,
    pathArgs,
    queryArgs,
  };
}

function sampleValue(schema: any): unknown {
  if (schema && typeof schema === "object") {
    if (schema.default !== undefined) return schema.default;
    if (Array.isArray(schema.enum) && schema.enum.length > 0) return schema.enum[0];
    if (schema.const !== undefined) return schema.const;
  }

  switch (schemaType(schema)) {
    case "integer":
    case "number":
      return 1;
    case "boolean":
      return true;
    case "array":
      return ["1"];
    case "object":
      return {};
    default:
      return "1";
  }
}

function schemaType(schema: any): string {
  if (!schema || typeof schema !== "object") return "any";
  const rawType = Array.isArray(schema.type) ? schema.type.find((t: string) => t !== "null") : schema.type;
  switch (rawType) {
    case "integer":
      return "integer";
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "string":
      return "string";
    case "array":
      return "array";
    case "object":
      return "object";
    default:
      if (schema.properties) return "object";
      if (schema.items) return "array";
      return "any";
  }
}

function isReadOnly(tool: ToolDef): boolean {
  const method = String(tool.method || "get").toUpperCase();
  return method === "GET" || method === "HEAD" || method === "OPTIONS";
}

function normalizeBaseUrl(url: string): string {
  const value = String(url ?? "").trim().replace(/\{[^}]+\}/g, "localhost");
  if (!value) return "http://localhost";
  if (/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(value)) return value;
  if (value.startsWith("//")) return `https:${value}`;
  return `http://localhost${value.startsWith("/") ? value : `/${value}`}`;
}
